class PhoneNumber:
    def __init__(self, number_str):
        # 1. Check for letters first
        if any(char.isalpha() for char in number_str):
            raise ValueError("letters not permitted")

        # 2. Check for invalid punctuation
        # Define allowed non-digit characters that are considered formatting
        allowed_formatting_chars = {'+', '(', ')', '-', '.', ' '}
        for char in number_str:
            if not char.isdigit() and char not in allowed_formatting_chars:
                # If it's not a digit and not an allowed formatting character
                raise ValueError("punctuations not permitted")

        # 3. Filter out all non-digit characters to get a raw digit string
        digits_only = "".join(filter(str.isdigit, number_str))

        # 4. Length Validation
        if len(digits_only) < 10:
            raise ValueError("must not be fewer than 10 digits")
        if len(digits_only) > 11:
            raise ValueError("must not be greater than 11 digits")

        # 5. Country Code Validation (if 11 digits)
        if len(digits_only) == 11:
            if digits_only[0] != '1':
                raise ValueError("11 digits must start with 1")
            else:
                digits_only = digits_only[1:]  # Remove country code

        # After cleaning, the number must be exactly 10 digits.
        # This is implicitly handled by the previous length checks and country code removal.
        # If the original number was 10 digits, it remains 10.
        # If it was 11 digits and started with '1', it becomes 10.
        # Other cases would have raised a ValueError already.

        # 6. Extract components
        area_code = digits_only[0:3]
        exchange_code = digits_only[3:6]
        subscriber_number = digits_only[6:10]

        # 7. Area Code Validation (NANP: NXX where N is 2-9)
        if area_code[0] == '0':
            raise ValueError("area code cannot start with zero")
        if area_code[0] == '1':
            raise ValueError("area code cannot start with one")

        # 8. Exchange Code Validation (NANP: NXX where N is 2-9)
        if exchange_code[0] == '0':
            raise ValueError("exchange code cannot start with zero")
        if exchange_code[0] == '1':
            raise ValueError("exchange code cannot start with one")

        # If all checks pass, store the cleaned number and its parts
        self.number = digits_only
        self.area_code = area_code
        self.exchange_code = exchange_code
        self.subscriber_number = subscriber_number
